// floating finder: every placed piece of the map that touches nothing else and stands on nothing
(() => {
  const g = __dmh, W = g.world, L = (W.scanAll || []).map((r, i) => ({ i, id: r[0], glow: r[1], ch: r[2], b: r[3] }));
  const T = 6, cell = 400, H = new Map(), key = (x, y, z) => x + ',' + y + ',' + z;
  for (const o of L) { const b = o.b; for (let x = Math.floor((b.min.x - T) / cell); x <= Math.floor((b.max.x + T) / cell); x++) for (let y = Math.floor((b.min.y - T) / cell); y <= Math.floor((b.max.y + T) / cell); y++) for (let z = Math.floor((b.min.z - T) / cell); z <= Math.floor((b.max.z + T) / cell); z++) { const k = key(x, y, z); let a = H.get(k); if (!a) H.set(k, a = []); if (a.length < 4000) a.push(o); } }
  const touch = (a, b) => a.min.x - T <= b.max.x && a.max.x + T >= b.min.x && a.min.y - T <= b.max.y && a.max.y + T >= b.min.y && a.min.z - T <= b.max.z && a.max.z + T >= b.min.z;
  const V = g.player.pos.constructor, out = [];
  for (const o of L) {
    const b = o.b, sz = [b.max.x - b.min.x, b.max.y - b.min.y, b.max.z - b.min.z];
    if (Math.max(...sz) > 20000) continue;
    let ok = false;
    const cx0 = Math.floor((b.min.x - T) / cell), cx1 = Math.floor((b.max.x + T) / cell), cy0 = Math.floor((b.min.y - T) / cell), cy1 = Math.floor((b.max.y + T) / cell), cz0 = Math.floor((b.min.z - T) / cell), cz1 = Math.floor((b.max.z + T) / cell);
    outer: for (let x = cx0; x <= cx1; x++) for (let y = cy0; y <= cy1; y++) for (let z = cz0; z <= cz1; z++) { for (const p of H.get(key(x, y, z)) || []) if (p !== o && touch(b, p.b)) { ok = true; break outer; } }
    if (ok) continue;
    // or standing on the floor / ground (anything solid under it within the tolerance)
    const cx = (b.min.x + b.max.x) / 2, cz = (b.min.z + b.max.z) / 2, h = g.phys.raycastDown(new V(cx, b.min.y + 40, cz), 60, false);
    if (h && h.point.y >= b.min.y - T - 2) continue;
    if (b.min.y < -50) continue;   // sunk into the ground
    out.push([o.i, o.id, o.glow, o.ch, Math.round(cx), Math.round(b.min.y), Math.round(cz), sz.map(Math.round)]);
  }
  window.__float = out;
  return JSON.stringify({ n: L.length, floating: out.length, sample: out.slice(0, 400) });
})()
